import java.util.*;
import java.io.*;

public class Main {
    static int n, countTotal, result;
    static long[] prefixSum = new long[15];
    static List<Long>[] data = new ArrayList[15];

    static {
        for (int i = 0; i < 15; i++) {
            data[i] = new ArrayList<>();
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n = Integer.parseInt(br.readLine().trim());
        generateSequences(0, 0);
        for (int i = 0; i <= 7; i++) {
            Collections.sort(data[i]);
        }
        countTotal = 0;
        result = 0;
        for (int i = 1; i <= 9; i++) {
            processSequences(i);
        }
        System.out.println(result);
    }

    static void generateSequences(int depth, long num) {
        if (depth == 7) return;
        countTotal++;
        long val = ((countTotal - num) % 998244353 + 998244353) % 998244353;
        data[depth].add(val);
        prefixSum[depth] = (prefixSum[depth] + val) % 1000000007;
        for (int digit = 0; digit <= 9; digit++) {
            generateSequences(depth + 1, num * 10 + digit);
        }
    }

    static void processSequences(long x) {
        if (x > n) return;
        if (x * 1000000 + 999999 <= n && x * 10 * 1000000 > n) {
            long currentCount = countTotal;
            for (int i = 0, factor = 1; i <= 6; i++, factor *= 10) {
                int sizeVec = data[i].size();
                long diffVal = ((currentCount - x * factor) % 998244353 + 998244353) % 998244353;
                int position = lowerBound(data[i], 1000000000 - diffVal);
                result = (int)((result + diffVal * sizeVec + prefixSum[i]) % 1000000007);
                long temp = (998244353L * (sizeVec - position)) % 1000000007;
                result = (int)((result - temp + 1000000007) % 1000000007);
                countTotal += sizeVec;
            }
            return;
        }
        countTotal++;
        long tempVal = ((countTotal - x) % 998244353 + 998244353) % 998244353;
        result = (int)((result + tempVal) % 1000000007);
        for (int i = 0; i <= 9; i++) {
            processSequences(x * 10 + i);
        }
    }

    static int lowerBound(List<Long> list, long key) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) >= key) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }
}
